/**
 * n8n Code Node
 * Cleans and validates multiple student records.
 * Mode: Run Once for All Items
 */

const items = $input.all();

function cleanStudent(student) {
  // Clean string values and remove extra spaces
  const cleaned = {};

  for (const [key, value] of Object.entries(student)) {
    cleaned[key] =
      typeof value === "string"
        ? value.trim()
        : value;
  }

  // Validate email
  const email = cleaned.Email;

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (
    typeof email !== "string" ||
    !emailRegex.test(email) ||
    email.toUpperCase() === "INVALID_EMAIL"
  ) {
    cleaned.Email = "INVALID_EMAIL";
  } else {
    cleaned.Email = email.toLowerCase();
  }

  // Clean and validate phone number
  if (cleaned.Phone !== undefined && cleaned.Phone !== null) {
    const phone = String(cleaned.Phone).replace(/\D/g, "");

    cleaned.Phone = /^[6-9]\d{9}$/.test(phone)
      ? phone
      : null;
  }

  // Validate Student_ID
  if (
    typeof cleaned.Student_ID !== "string" ||
    cleaned.Student_ID.trim() === ""
  ) {
    cleaned.Student_ID = null;
  }

  // Clean name
  if (typeof cleaned.Name === "string") {
    cleaned.Name = cleaned.Name.replace(/\s+/g, " ");
    if (cleaned.Name === "") cleaned.Name = null;
  }

  // Normalize course and city
  for (const field of ["Course", "City"]) {
    if (typeof cleaned[field] === "string") {
      cleaned[field] = cleaned[field].trim();
    }
  }

  // Normalize Fee_Paid to boolean
  if (typeof cleaned.Fee_Paid === "string") {
    const value = cleaned.Fee_Paid.toLowerCase();

    if (["true", "yes", "1"].includes(value)) {
      cleaned.Fee_Paid = true;
    } else if (["false", "no", "0"].includes(value)) {
      cleaned.Fee_Paid = false;
    } else {
      cleaned.Fee_Paid = null;
    }
  } else if (typeof cleaned.Fee_Paid !== "boolean") {
    cleaned.Fee_Paid = null;
  }

  // Validate date in YYYY-MM-DD format
  const date = cleaned.Enrolled_Date;
  const dateRegex = /^\d{4}-\d{2}-\d{2}$/;

  if (typeof date === "string" && dateRegex.test(date)) {
    const parsed = new Date(`${date}T00:00:00Z`);

    const validDate =
      !Number.isNaN(parsed.getTime()) &&
      parsed.toISOString().slice(0, 10) === date;

    cleaned.Enrolled_Date = validDate ? date : null;
  } else {
    cleaned.Enrolled_Date = null;
  }

  return cleaned;
}

// Parse each incoming n8n item
function parseRecord(item) {
  let data = item.json;

  // Handle AI output wrapped in a text field
  if (typeof data === "string") {
    data = JSON.parse(data);
  } else if (typeof data.output === "string") {
    data = JSON.parse(data.output);
  } else if (typeof data.text === "string") {
    data = JSON.parse(data.text);
  }

  // Handle arrays of student records
  return Array.isArray(data) ? data : [data];
}

const results = [];
const errors = [];

for (let i = 0; i < items.length; i++) {
  try {
    const records = parseRecord(items[i]);

    for (const record of records) {
      if (
        !record ||
        typeof record !== "object" ||
        Array.isArray(record)
      ) {
        errors.push({
          inputItem: i,
          error: "Invalid student record"
        });
        continue;
      }

      results.push({
        json: cleanStudent(record)
      });
    }
  } catch (error) {
    errors.push({
      inputItem: i,
      error: "Could not parse JSON: " + error.message
    });
  }
}

// Return one output item per student.
// Invalid JSON records are excluded and reported in a separate output field.
return results.map(item => ({
  json: {
    ...item.json,
    _parseErrors: errors
  }
}));
